SELECT STEP, LEVER_TYPE, IMPACT_EUR_M, CIR_PCT_AFTER, ROE_PCT_AFTER
FROM SDP_AKTIA.PUBLIC.AKTIA_CIR_BRIDGE
ORDER BY SORT_ORDER;

SELECT METRIC, BASE_VALUE, SCENARIO_VALUE, SCENARIO_VALUE - BASE_VALUE AS change
FROM SDP_AKTIA.PUBLIC.AKTIA_SCENARIO_RESULTS
WHERE SCENARIO IN ('Euribor -50bp', 'AUM +5%', 'Combined') AND FISCAL_YEAR = 2027;
